changeSet.sql:
      create function on_members_inserted() returns trigger
        language plpgsql as $$
      begin
      insert into processable_members (member_id, view_id, collection_id)
      select nm.member_id, v.view_id, nm.collection_id
      from new_members nm
             join views v on v.collection_id = nm.collection_id on conflict do nothing;
      return null;
      end
$$;
